export const teachingTables = tables;
const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
export function knowledgePoints(u) {
  return u.concept.split(/。|；/).map(s=>s.trim()).filter(Boolean);
}
export function teachingFor(u) {
  return tables[u.id] || {title: '概念、應用與界線對照', rows:[
    ...knowledgePoints(u).map((point,i)=>['核心 '+(i+1),point,'試著用下方例題，說明這項概念如何影響判斷。']),
    ['應用情境',u.example,'先辨識已知條件，再對照上列概念。'],
    ['易錯界線',u.pitfall,'提出一個會犯此錯誤的例子，再改正理由。']
  ]};
}
export function renderTeaching(u) {
 const t=teachingFor(u);
 return `<section class="teaching-notes" aria-label="逐點學習與比較表"><h3>拆開理解，再連起來</h3><ol class="knowledge-list">${knowledgePoints(u).map(p=>`<li>${esc(p)}。</li>`).join('')}</ol><div class="table-wrap"><table class="teaching-table"><caption>${esc(t.title)}</caption><thead><tr><th scope="col">辨識重點</th><th scope="col">規則／條件</th><th scope="col">例子／檢查方法</th></tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><details class="worked-retrieval"><summary>先遮住講義：我能解釋「${esc(u.title)}」嗎？</summary><p>先口頭說出核心概念，再展開上表核對。最後完成這項遷移任務：</p><p>${esc(u.task)}</p><p class="subtle">能認出答案只是第一步；還要能說明理由、條件，以及何時不能套用。</p></details></section>`;
}
